/**
 * Golden-vector tests: the offline engine must reproduce the Python reference (qgdevs) to round-off.
 * golden.json is generated by tools/golden_vectors.py from the reference implementation.
 */
import { describe, expect, it } from 'vitest';
import type { Design, Environment, PredictResult } from '../lib/types';
import golden from './golden.json';
import {
  checkGeometry, decoherenceBudget, eftPotentialTerms, getMaterial, clausiusMossotti, minDistanceForGravityDominance,
  modelCurves, parallelDeltaPhiAnalytic, predictScenario, radiusOf, IMPLEMENTED_IDS, predictionsTable, cslRate,
  spinDipolarBranchEnergies,
} from './index';
import { entanglingPhase } from './bmv';
import { BRANCHES } from '../lib/types';
import { hbar } from './constants';

/* eslint-disable @typescript-eslint/no-explicit-any */
const cases: any[] = (golden as any).cases;

const num = (v: any): number => (v === 'Infinity' ? Infinity : v === '-Infinity' ? -Infinity : v === null ? NaN : v);

// Tolerances.
// Phases, energies, distances and decoherence rates are closed-form arithmetic: relative 1e-9.
const RTOL_PHYS = 1e-9;
// Entanglement measures involve eigen/singular-value problems: relative 1e-8.
const RTOL_MEAS = 1e-8;
// Absolute floor for measures: quantities that are exactly zero in exact arithmetic come out of either
// implementation as round-off noise (e.g. negativity 1.4e-16 at t = 0, correlators ±5e-17); a relative
// comparison of two round-off values is meaningless. 1e-13 is ~1000 ε and far below any physical signal.
const ATOL_MEAS = 1e-13;
// No special floor is needed for the concurrence of (numerically) pure states: the one-sided Jacobi SVD
// matches the reference to the same tolerance (checked).
// Phase conditioning: every measure is a smooth function of the branch phases with derivative ≤ O(1) per
// radian, but only Δφ mod 2π matters. When a residual charge drives |φ_ij| to 1e9–1e12 rad, float64 fixes
// the phases (in the reference and here) only to ~ε·|φ|, so measures are determined only to that level.
// For such cases the absolute floor is 16·ε·max|φ_ij| (inactive, i.e. < ATOL_MEAS, whenever max|φ| < 28 rad).
const EPS = 2.220446049250313e-16;
let condFloor = 0;

let assertions = 0;
function close(actual: number, expected: number, rtol: number, atol: number, label: string) {
  assertions++;
  if (!Number.isFinite(expected)) {
    expect(actual, label).toBe(expected);
    return;
  }
  const err = Math.abs(actual - expected);
  const tol = rtol * Math.abs(expected) + atol;
  if (!(err <= tol)) throw new Error(`${label}: got ${actual}, expected ${expected} (|Δ| = ${err.toExponential(3)} > ${tol.toExponential(3)})`);
}
const phys = (a: number, e: any, l: string) => close(a, num(e), RTOL_PHYS, 0, l);
const meas = (a: number, e: any, l: string, atol = ATOL_MEAS) => close(a, num(e), RTOL_MEAS, Math.max(atol, condFloor), l);

function inputs(c: any): { design: Design; env: Environment } {
  return { design: c.inputs.design as Design, env: c.inputs.environment as Environment };
}

describe('golden vectors (Python reference)', () => {
  it('has ~40 admissible cases and some inadmissible ones', () => {
    expect(cases.filter((c) => c.admissible).length).toBeGreaterThanOrEqual(40);
    expect(cases.filter((c) => !c.admissible).length).toBeGreaterThanOrEqual(2);
  });

  cases.forEach((c, idx) => {
    const { design, env } = inputs(c);
    const name = `case ${idx} (${design.geometry}, ${env.material}, m=${design.mass_A.toExponential(2)} kg)`;
    if (!c.admissible) {
      it(`${name}: inadmissible design gives the same issues`, () => {
        expect(checkGeometry(design)).toEqual(c.issues);
        expect(predictScenario(design, env)).toEqual({ admissibility_issues: c.issues });
      });
      return;
    }
    it(`${name}: prediction matches`, () => {
      const g = c.predict;
      condFloor = 16 * EPS * Math.max(...Object.values(g.phases_rad as Record<string, number>).map(Math.abs));
      const r = predictScenario(design, env, 12) as PredictResult;
      expect(r.admissibility_issues).toEqual([]);
      for (const k of ['LL', 'LR', 'RL', 'RR'] as const) {
        phys(r.branch_distances_m[k], g.branch_distances_m[k], `${name} r_${k}`);
        phys(r.gravitational_energies_J[k], g.gravitational_energies_J[k], `${name} Ug_${k}`);
        phys(r.total_energies_J[k], g.total_energies_J[k], `${name} U_${k}`);
        phys(r.phases_rad[k], g.phases_rad[k], `${name} φ_${k}`);
        for (const ch of Object.keys(g.nongrav_channels[k])) {
          close(r.nongrav_channels[k][ch], g.nongrav_channels[k][ch], RTOL_PHYS, 0, `${name} ${ch}_${k}`);
        }
      }
      for (const p of ['A_L', 'A_R', 'B_L', 'B_R'] as const)
        for (let i = 0; i < 3; i++) close(r.branch_positions[p][i], g.branch_positions[p][i], RTOL_PHYS, 1e-300, `${name} pos ${p}`);
      phys(r.design.radius_A, g.design.radius_A, 'radius_A');
      phys(r.design.gamma_A, g.design.gamma_A, 'gamma_A');
      phys(r.design.gamma_B, g.design.gamma_B, 'gamma_B');
      phys(r.delta_phi_gravity_rad, g.delta_phi_gravity_rad, `${name} Δφ_g`);
      phys(r.delta_phi_total_rad, g.delta_phi_total_rad, `${name} Δφ`);
      for (const k of ['alpha', 'beta', 'gamma', 'delta_phi'] as const) {
        // β, γ are differences of nearly equal phases: compare relative to the phase scale
        close(r.phase_decomposition[k], g.phase_decomposition[k], RTOL_PHYS, RTOL_PHYS * Math.abs(g.phase_decomposition.alpha), `${name} ${k}`);
      }
      meas(r.concurrence, g.concurrence, `${name} concurrence`);
      meas(r.negativity, g.negativity, `${name} negativity`);
      meas(r.log_negativity, g.log_negativity, `${name} log-negativity`);
      meas(r.purity, g.purity, `${name} purity`);
      meas(r.pure_state_concurrence_bound, g.pure_state_concurrence_bound, `${name} |sin Δφ/2|`);
      meas(r.witness_cpk_local_corrected, g.witness_cpk_local_corrected, `${name} CPK`);
      meas(r.witness_ppt.value, g.witness_ppt.value, `${name} PPT witness`);
      expect(r.witness_ppt.certifies_entanglement).toBe(g.witness_ppt.certifies_entanglement);
      expect(r.state_check.passed).toBe(g.state_check.passed);
      for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
        meas(r.density_matrix_real[i][j], g.density_matrix_real[i][j], `${name} ρre`);
        meas(r.density_matrix_imag[i][j], g.density_matrix_imag[i][j], `${name} ρim`);
      }
      // time series
      const ts = r.time_series!, gts = g.time_series;
      expect(ts.t.length).toBe(gts.t.length);
      gts.t.forEach((_: number, k: number) => {
        phys(ts.t[k], gts.t[k], 't');
        close(ts.delta_phi[k], gts.delta_phi[k], RTOL_PHYS, 1e-300, `${name} ts Δφ[${k}]`);
        meas(ts.concurrence[k], gts.concurrence[k], `${name} ts C[${k}]`);
        meas(ts.negativity[k], gts.negativity[k], `${name} ts N[${k}]`);
        meas(ts.witness_cpk[k], gts.witness_cpk[k], `${name} ts W[${k}]`);
        meas(ts.purity[k], gts.purity[k], `${name} ts P[${k}]`);
      });
      // decoherence budget of A
      expect(r.decoherence.dominant).toBe(g.decoherence.dominant);
      phys(r.decoherence.environmental_total_rate!, g.decoherence.environmental_total_rate, `${name} Γ_env (default budget)`);
      expect(r.decoherence.includes_hypothetical).toBe(false); // hypothetical collapse models are opt-in
      expect(Object.keys(r.decoherence.mechanisms).sort()).toEqual(Object.keys(g.decoherence.mechanisms).sort());
      phys(r.decoherence.total_rate, g.decoherence.total_rate, `${name} Γ_total`);
      for (const m of Object.keys(g.decoherence.mechanisms)) {
        phys(r.decoherence.mechanisms[m].rate, g.decoherence.mechanisms[m].rate, `${name} Γ_${m}`);
        meas(r.decoherence.mechanisms[m].coherence_factor, g.decoherence.mechanisms[m].coherence_factor, `${name} e^-Γt ${m}`);
      }
      // competing models
      expect(r.models.map((m) => m.id)).toEqual(g.models.map((m: any) => m.id));
      r.models.forEach((m, k) => {
        const gm = g.models[k];
        for (const f of ['negativity', 'witness_cpk', 'purity', 'coherence_A', 'coherence_B'] as const)
          meas(m[f], gm[f], `${name} ${m.id}.${f}`);
        meas(m.concurrence, gm.concurrence, `${name} ${m.id}.concurrence`);
        for (const s of Object.keys(gm.correlators)) meas(m.correlators[s], gm.correlators[s], `${name} ${m.id}.<${s}>`);
      });
    });

    it(`${name}: Diósi–Penrose, gravity-dominance distance, EFT terms`, () => {
      const R = radiusOf(design.mass_A, design.density);
      const cm = clausiusMossotti(getMaterial(env.material));
      const b = decoherenceBudget(design.mass_A, R, design.dx_A, {
        pressure: env.pressure, T_gas: env.T_gas, T_env: env.T_env, T_int: env.T_int, cm, t: design.time, include_dp: true,
        include_csl: true,
      });
      const g = c.dp_budget;
      // CSL: the reference integrates with adaptive quad (epsrel 1e-10 per subinterval); Gauss–Legendre here
      phys(b.mechanisms.csl_collapse.rate, g.mechanisms.csl_collapse.rate, `${name} Γ_CSL`);
      expect(b.mechanisms.csl_collapse.hypothetical).toBe(true);
      expect(b.mechanisms.diosi_penrose_collapse.hypothetical).toBe(true);
      phys(b.environmental_total_rate!, g.environmental_total_rate, `${name} Γ_env`);
      expect(b.includes_hypothetical).toBe(g.includes_hypothetical);
      phys(b.suggested_display_window_s!, g.suggested_display_window_s, `${name} display window`);
      // DP: the reference integrates U(0) numerically (quad, epsrel 1e-12); the closed form is exact
      phys(b.mechanisms.diosi_penrose_collapse.rate, g.mechanisms.diosi_penrose_collapse.rate, `${name} Γ_DP`);
      phys(b.total_rate, g.total_rate, `${name} Γ_total(DP)`);
      expect(b.dominant).toBe(g.dominant);
      phys(minDistanceForGravityDominance(design.mass_A, R, cm.re, 0.1), c.min_distance_gravity_dominance, `${name} r_min`);
      const eft = eftPotentialTerms(design.mass_A, design.mass_B, design.separation);
      for (const k of Object.keys(c.eft)) phys((eft as any)[k], c.eft[k], `${name} eft ${k}`);
    });

    it(`${name}: model curves match predictions_table at several times`, () => {
      condFloor = 16 * EPS * Math.max(...Object.values(c.predict.phases_rad as Record<string, number>).map(Math.abs));
      const times = c.curves.map((x: any) => x.t);
      const ids = [...IMPLEMENTED_IDS];
      const cv = modelCurves(design, env, ids, times);
      c.curves.forEach((row: any, k: number) => {
        row.models.forEach((gm: any) => {
          meas(cv[gm.id].negativity[k], gm.negativity, `${name} curve ${gm.id} N(t${k})`);
          meas(cv[gm.id].witness[k], gm.witness_cpk, `${name} curve ${gm.id} W(t${k})`);
          meas(cv[gm.id].concurrence[k], gm.concurrence, `${name} curve ${gm.id} C(t${k})`);
        });
      });
    });
  });

  it('counts assertions', () => {
    condFloor = 0;
    console.log(`golden assertions: ${assertions}`);
    expect(assertions).toBeGreaterThan(1000);
  });
});

describe('analytic checks', () => {
  const base: Design = {
    mass_A: 1e-14, mass_B: 1e-14, density: 3510, separation: 450e-6, dx_A: 250e-6, dx_B: 250e-6,
    geometry: 'parallel', angle_deg: 90, time: 2.5, gamma_A: 0, gamma_B: 0,
  };
  const vacuum: Environment = {
    pressure: 0, T_gas: 0.15, T_env: 0, T_int: 0, material: 'diamond', residual_charge_e: 0, include_casimir: false, readout_error: 0.01,
  };

  it('parallel-geometry Δφ equals the closed form 2Gm²t/ħ (1/d − 1/√(d²+Δx²))', () => {
    const r = predictScenario(base, vacuum) as PredictResult;
    const a = parallelDeltaPhiAnalytic(1e-14, 1e-14, 450e-6, 250e-6, 2.5);
    expect(Math.abs(r.delta_phi_gravity_rad - a) / a).toBeLessThan(1e-12);
  });

  it('pure-state concurrence equals |sin(Δφ/2)| and negativity = C/2', () => {
    const r = predictScenario(base, vacuum) as PredictResult;
    expect(r.purity).toBeCloseTo(1, 14);
    expect(Math.abs(r.concurrence - Math.abs(Math.sin(r.delta_phi_total_rad / 2)))).toBeLessThan(1e-8);
    expect(Math.abs(r.negativity - r.concurrence / 2)).toBeLessThan(1e-8);
  });

  it('negativity ≥ 0 for every hypothesis; SC-MF, CC-KTM and NULL-NG never entangle through gravity', () => {
    // The NV spin–spin channel is always present and is itself entangling, so the gravity-only statement is
    // checked with the non-gravitational branch energies switched off.
    const zero = { LL: 0, LR: 0, RL: 0, RR: 0 };
    for (const time of [0.5, 2.5, 6]) {
      const r = predictScenario({ ...base, time }, vacuum) as PredictResult;
      for (const m of r.models) expect(m.negativity).toBeGreaterThanOrEqual(0);
      const rows = predictionsTable({ design: { ...base, time }, gamma_env_A: 0, gamma_env_B: 0, nongrav: zero }, ['SC-MF', 'CC-KTM', 'NULL-NG', 'QG-COH']);
      for (const id of ['SC-MF', 'CC-KTM', 'NULL-NG']) {
        const m = rows.find((x) => x.id === id)!;
        expect(m.negativity, id).toBeLessThan(1e-13);
        expect(m.witness_cpk, id).toBeGreaterThanOrEqual(-1e-12);
      }
      expect(rows.find((x) => x.id === 'QG-COH')!.negativity).toBeGreaterThan(0);
    }
  });

  it('NV spin–spin coupling is present and entangling: Δφ_ss = −(t/ħ)(U_LL+U_RR−U_LR−U_RL) ≠ 0', () => {
    const U = spinDipolarBranchEnergies(base);
    const ph = {} as Record<(typeof BRANCHES)[number], number>;
    for (const k of BRANCHES) ph[k] = (-U[k] * base.time) / hbar;
    expect(Math.abs(entanglingPhase(ph))).toBeGreaterThan(0);
    expect(U.LL).toBeGreaterThan(0); // parallel spins side by side (θ = 90°): repulsive
  });

  it('CSL rate reduces to λ(m/m0)²(1 − e^{−Δx²/4r_C²}) for point-like bodies (R ≪ r_C)', () => {
    const m = 1e-20, R = 1e-9, dx = 3e-7, m0 = 1.66053906892e-27, rC = 1e-7;
    const exact = 1e-16 * (m / m0) ** 2 * (1 - Math.exp(-(dx * dx) / (4 * rC * rC)));
    expect(Math.abs(cslRate(m, R, dx).rate / exact - 1)).toBeLessThan(1e-4); // finite-R form factor ~ (R/r_C)²
  });

  it('model curves at t = 0 give the product state |+>|+> (no entanglement, CPK = 0)', () => {
    const cv = modelCurves(base, vacuum, ['QG-COH', 'CC-KTM'], [0]);
    expect(cv['QG-COH'].negativity[0]).toBeLessThan(1e-13);
    expect(Math.abs(cv['QG-COH'].witness[0])).toBeLessThan(1e-13);
    expect(cv['CC-KTM'].concurrence[0]).toBeLessThan(1e-7);
  });
});
